{
  "findings": [
    {
      "check_id": "CKV2_GCP_19",
      "title": "Ensure GCP Kubernetes engine clusters have 'alpha cluster' feature disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Enabling Kubernetes alpha features can introduce instability and security risks as these features are not production-ready."
    },
    {
      "check_id": "CKV_GCP_7",
      "title": "Ensure Legacy Authorization is set to Disabled on Kubernetes Engine Clusters",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Legacy ABAC authorization is less secure and should be disabled in favor of RBAC for better access control."
    },
    {
      "check_id": "CKV_GCP_13",
      "title": "Ensure client certificate authentication to Kubernetes Engine Clusters is disabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Client certificate authentication can expose sensitive credentials and should be disabled to reduce attack surface."
    },
    {
      "check_id": "CKV_GCP_25",
      "title": "Ensure Kubernetes Cluster is created with Private cluster enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Private clusters enhance security by restricting access to the control plane and nodes to private IPs."
    },
    {
      "check_id": "CKV_GCP_64",
      "title": "Ensure clusters are created with Private Nodes",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "Private nodes ensure that nodes do not have public IPs, reducing exposure to external threats."
    }
  ],
  "patched_code": "resource \"google_container_cluster\" \"k8sexample\" {\n  name               = \"${var.vault_user}-k8s-cluster\"\n  description        = \"example k8s cluster\"\n  zone               = \"${var.gcp_zone}\"\n  initial_node_count = \"${var.initial_node_count}\"\n  enable_kubernetes_alpha = false\n  enable_legacy_abac = false\n  master_auth {\n    username = \"${var.master_username}\"\n    password = \"${var.master_password}\"\n    client_certificate_config {\n      issue_client_certificate = false\n    }\n  }\n  node_config {\n    machine_type = \"${var.node_machine_type}\"\n    disk_size_gb = \"${var.node_disk_size}\"\n    oauth_scopes = [\n      \"https://www.googleapis.com/auth/compute\",\n      \"https://www.googleapis.com/auth/devstorage.read_only\",\n      \"https://www.googleapis.com/auth/logging.write\",\n      \"https://www.googleapis.com/auth/monitoring\"\n    ]\n  }\n  private_cluster_config {\n    enable_private_nodes = true\n    enable_private_endpoint = true\n  }\n}",
  "fix_summary": "Disabled Kubernetes alpha features, legacy ABAC authorization, and client certificate authentication. Enabled private cluster and private nodes for enhanced security."
}
